    private fun combineFloatArrays(vararg chunks: FloatArray): FloatArray {
        var totalSize = 0
        chunks.forEach { totalSize += it.size }
        val result = FloatArray(totalSize)
        var offset = 0
        chunks.forEach { chunk ->
            chunk.copyInto(result, destinationOffset = offset)
            offset += chunk.size
        }
        return result
    }
